"""Weighted reductions for labeled arrays and datasets."""

from .computation import dot
from .duck_array_ops import isnull
from .options import _get_keep_attrs
from .pycompat import dask_array_type


class Weighted:
    """An object for weighted reductions of a DataArray or Dataset.

    Construct these objects with ``DataArray.weighted`` or ``Dataset.weighted``.
    Weights are aligned and broadcast by dimension name and coordinate label.
    """

    __slots__ = ("obj", "weights")

    def __init__(self, obj, weights):
        from .dataarray import DataArray

        if not isinstance(weights, DataArray):
            raise ValueError("`weights` must be a DataArray")

        def check_weights(data):
            if isnull(data).any():
                raise ValueError(
                    "`weights` cannot contain missing values. "
                    "Missing values can be replaced by `weights.fillna(0)`."
                )
            return data

        if isinstance(weights.data, dask_array_type):
            # Validate each block when evaluated, without computing eagerly.
            weights = weights.copy(
                data=weights.data.map_blocks(check_weights, dtype=weights.dtype)
            )
        else:
            check_weights(weights.data)

        self.obj = obj
        self.weights = weights

    def __repr__(self):
        return "{} with weights along dimensions: {}".format(
            type(self).__name__, ", ".join(map(str, self.weights.dims))
        )

    def _check_dim(self, dim):
        if dim is None or dim is ...:
            return dim
        if isinstance(dim, str):
            dim = (dim,)
        else:
            dim = tuple(dim)
        missing = set(dim) - set(self.obj.dims) - set(self.weights.dims)
        if missing:
            raise ValueError("Dimensions {} not found in data or weights".format(missing))
        return dim

    @staticmethod
    def _reduce(da, weights, dim=None, skipna=None):
        if skipna or (skipna is None and da.dtype.kind in "cfO"):
            da = da.fillna(0.0)
        # A dot product avoids materializing the broadcast data * weights array.
        return dot(da, weights, dims=... if dim is None else dim)

    def _sum_of_weights(self, da, dim=None):
        # Missing data must not contribute to the normalization. Cast the mask
        # to count observations correctly even when weights are boolean.
        sum_of_weights = self._reduce(da.notnull().astype(int), self.weights, dim)
        return sum_of_weights.where(sum_of_weights != 0)

    def _weighted_sum(self, da, dim=None, skipna=None):
        return self._reduce(da, self.weights, dim, skipna)

    def _weighted_mean(self, da, dim=None, skipna=None):
        return self._weighted_sum(da, dim, skipna) / self._sum_of_weights(da, dim)

    def _implementation(self, func, dim, keep_attrs, **kwargs):
        raise NotImplementedError

    def sum_of_weights(self, dim=None, keep_attrs=None):
        """Sum weights over dimensions, excluding weights at missing data.

        Parameters
        ----------
        dim : str or sequence of str, optional
            Dimensions to reduce. By default, reduce all dimensions.
        keep_attrs : bool, optional
            Copy attributes from the original object if True.

        Returns
        -------
        DataArray or Dataset
            Sum of valid weights. Zero sums are replaced by NaN.
        """
        return self._implementation(self._sum_of_weights, dim, keep_attrs)

    def sum(self, dim=None, skipna=None, keep_attrs=None):
        """Compute the weighted sum over one or more dimensions.

        Parameters
        ----------
        dim : str or sequence of str, optional
            Dimensions to reduce. By default, reduce all dimensions.
        skipna : bool, optional
            Skip missing values. By default, missing values are skipped for
            floating point, complex and object data.
        keep_attrs : bool, optional
            Copy attributes from the original object if True.

        Returns
        -------
        DataArray or Dataset
            Weighted sum. An all-missing slice has sum zero when skipping NaN.
        """
        return self._implementation(self._weighted_sum, dim, keep_attrs, skipna=skipna)

    def mean(self, dim=None, skipna=None, keep_attrs=None):
        """Compute the weighted mean over one or more dimensions.

        Parameters
        ----------
        dim : str or sequence of str, optional
            Dimensions to reduce. By default, reduce all dimensions.
        skipna : bool, optional
            Skip missing values. By default, missing values are skipped for
            floating point, complex and object data.
        keep_attrs : bool, optional
            Copy attributes from the original object if True.

        Returns
        -------
        DataArray or Dataset
            Weighted mean. Slices with zero valid weight return NaN.
        """
        return self._implementation(self._weighted_mean, dim, keep_attrs, skipna=skipna)


class DataArrayWeighted(Weighted):
    """Weighted reductions for a DataArray."""

    __slots__ = ()

    def _implementation(self, func, dim, keep_attrs, **kwargs):
        dim = self._check_dim(dim)
        result = func(self.obj, dim=dim, **kwargs)
        result.name = self.obj.name
        if keep_attrs is None:
            keep_attrs = _get_keep_attrs(default=False)
        result.attrs = self.obj.attrs if keep_attrs else {}
        return result


class DatasetWeighted(Weighted):
    """Weighted reductions for each data variable in a Dataset."""

    __slots__ = ()

    def _implementation(self, func, dim, keep_attrs, **kwargs):
        dim = self._check_dim(dim)
        if keep_attrs is None:
            keep_attrs = _get_keep_attrs(default=False)

        def reduce_variable(da):
            result = func(da, dim=dim, **kwargs)
            result.attrs = da.attrs if keep_attrs else {}
            return result

        return self.obj.map(reduce_variable, keep_attrs=keep_attrs)

